package com.example.reconciliation.batch;

import com.example.reconciliation.domain.ReconciledTransaction;
import com.example.reconciliation.domain.TransactionRecord;
import org.springframework.batch.core.Job;
import org.springframework.batch.core.Step;
import org.springframework.batch.core.job.builder.JobBuilder;
import org.springframework.batch.core.repository.JobRepository;
import org.springframework.batch.core.step.builder.StepBuilder;
import org.springframework.batch.item.ItemProcessor;
import org.springframework.batch.item.ItemReader;
import org.springframework.batch.item.ItemWriter;
import org.springframework.batch.item.file.FlatFileItemReader;
import org.springframework.batch.item.file.builder.FlatFileItemReaderBuilder;
import org.springframework.batch.item.file.mapping.RecordFieldSetMapper;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.io.FileSystemResource;
import org.springframework.transaction.PlatformTransactionManager;

import java.math.BigDecimal;

@Configuration
public class FirstBatchJobConfig {

    private final JobRepository jobRepository;
    private final PlatformTransactionManager transactionManager;

    public FirstBatchJobConfig(JobRepository jobRepository,
                               PlatformTransactionManager transactionManager) {
        this.jobRepository = jobRepository;
        this.transactionManager = transactionManager;
    }

    @Bean
    public Job firstReconciliationJob() {
        // A Job is a container of Steps. It is repeatable and restartable
        // because the JobRepository tracks every execution.
        return new JobBuilder("firstReconciliationJob", jobRepository)
                .start(reconciliationStep())
                .build();
    }

    @Bean
    public Step reconciliationStep() {
        // chunk(50) = read up to 50 items, process them, write them in ONE transaction.
        // If the JVM crashes after 10 chunks, the restart resumes from chunk 11.
        return new StepBuilder("reconciliationStep", jobRepository)
                .<TransactionRecord, ReconciledTransaction>chunk(50, transactionManager)
                .reader(transactionReader())
                .processor(reconciliationProcessor())
                .writer(reconciliationWriter())
                .build();
    }

    @Bean
    public FlatFileItemReader<TransactionRecord> transactionReader() {
        return new FlatFileItemReaderBuilder<TransactionRecord>()
                .name("transactionReader")
                .resource(new FileSystemResource("data/transactions.csv"))
                .linesToSkip(1) // skip header
                .delimited()
                .names("transactionId", "accountId", "amount", "currency", "transactionDate", "status")
                .fieldSetMapper(new RecordFieldSetMapper<>(TransactionRecord.class))
                .build();
    }

    @Bean
    public ItemProcessor<TransactionRecord, ReconciledTransaction> reconciliationProcessor() {
        return record -> {
            // Simplified reconciliation logic: positive amount + SETTLED status = MATCHED
            boolean matched = record.amount() != null
                    && record.amount().compareTo(BigDecimal.ZERO) > 0
                    && "SETTLED".equals(record.status());

            return new ReconciledTransaction(
                    record.transactionId(),
                    record.accountId(),
                    record.amount(),
                    matched ? "MATCHED" : "MISMATCHED",
                    matched ? "Auto-matched on first run" : "Amount or status mismatch"
            );
        };
    }

    @Bean
    public ItemWriter<ReconciledTransaction> reconciliationWriter() {
        // In production: JdbcBatchItemWriter inserting into reconciled_transactions table.
        // Here we simulate the write to show the contract.
        return chunk -> chunk.forEach(tx ->
            System.out.printf("[Writer] %s -> %s%n", tx.transactionId(), tx.reconciliationStatus())
        );
    }
}

package com.example.reconciliation.batch;

import com.example.reconciliation.domain.ReconciledTransaction;
import com.example.reconciliation.domain.TransactionRecord;
import org.springframework.batch.core.Job;
import org.springframework.batch.core.Step;
import org.springframework.batch.core.job.builder.JobBuilder;
import org.springframework.batch.core.repository.JobRepository;
import org.springframework.batch.core.step.builder.StepBuilder;
import org.springframework.batch.item.ItemProcessor;
import org.springframework.batch.item.ItemReader;
import org.springframework.batch.item.ItemWriter;
import org.springframework.batch.item.database.JdbcPagingItemReader;
import org.springframework.batch.item.database.builder.JdbcPagingItemReaderBuilder;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.transaction.PlatformTransactionManager;

import javax.sql.DataSource;
import java.math.BigDecimal;
import java.time.LocalDate;

@Configuration
public class BoundedBatchFromStreamConfig {

    private final JobRepository jobRepository;
    private final PlatformTransactionManager transactionManager;
    private final DataSource dataSource;

    public BoundedBatchFromStreamConfig(JobRepository jobRepository,
                                        PlatformTransactionManager transactionManager,
                                        DataSource dataSource) {
        this.jobRepository = jobRepository;
        this.transactionManager = transactionManager;
        this.dataSource = dataSource;
    }

    @Bean
    public Job nightlySettlementJob() {
        // This job runs at 02:00 and processes EXACTLY the previous day's transactions.
        // It has a defined boundary: transactionDate = yesterday.
        // It is not a stream consumer; it is a bounded snapshot read.
        return new JobBuilder("nightlySettlementJob", jobRepository)
                .start(settlementStep())
                .build();
    }

    @Bean
    public Step settlementStep() {
        return new StepBuilder("settlementStep", jobRepository)
                .<TransactionRecord, ReconciledTransaction>chunk(100, transactionManager)
                .reader(yesterdayTransactionReader())
                .processor(settlementProcessor())
                .writer(settlementWriter())
                .build();
    }

    @Bean
    public JdbcPagingItemReader<TransactionRecord> yesterdayTransactionReader() {
        // Bounded read: only transactions from yesterday.
        // This is a snapshot of the stream's accumulated state, not a live subscription.
        LocalDate yesterday = LocalDate.now().minusDays(1);

        return new JdbcPagingItemReaderBuilder<TransactionRecord>()
                .name("yesterdayTransactionReader")
                .dataSource(dataSource)
                .selectClause("SELECT transaction_id, account_id, amount, currency, transaction_date, status")
                .fromClause("FROM transactions")
                .whereClause("WHERE transaction_date = '" + yesterday + "'")
                .sortKeys("transaction_id")
                .pageSize(100)
                .rowMapper((rs, rowNum) -> new TransactionRecord(
                        rs.getString("transaction_id"),
                        rs.getString("account_id"),
                        rs.getBigDecimal("amount"),
                        rs.getString("currency"),
                        rs.getDate("transaction_date").toLocalDate(),
                        rs.getString("status")
                ))
                .build();
    }

    @Bean
    public ItemProcessor<TransactionRecord, ReconciledTransaction> settlementProcessor() {
        return record -> {
            boolean settled = "SETTLED".equals(record.status())
                    && record.amount() != null
                    && record.amount().compareTo(BigDecimal.ZERO) > 0;

            return new ReconciledTransaction(
                    record.transactionId(),
                    record.accountId(),
                    record.amount(),
                    settled ? "SETTLED" : "PENDING_REVIEW",
                    settled ? "End-of-day settlement" : "Requires manual review"
            );
        };
    }

    @Bean
    public ItemWriter<ReconciledTransaction> settlementWriter() {
        return chunk -> chunk.forEach(tx ->
            System.out.printf("[Settlement] %s -> %s%n", tx.transactionId(), tx.reconciliationStatus())
        );
    }
}

package com.example.reconciliation.batch;

import com.example.reconciliation.domain.ReconciledTransaction;
import com.example.reconciliation.domain.TransactionRecord;
import org.springframework.batch.core.Job;
import org.springframework.batch.core.Step;
import org.springframework.batch.core.job.builder.JobBuilder;
import org.springframework.batch.core.repository.JobRepository;
import org.springframework.batch.core.step.builder.StepBuilder;
import org.springframework.batch.item.ItemProcessor;
import org.springframework.batch.item.ItemReader;
import org.springframework.batch.item.ItemWriter;
import org.springframework.batch.item.file.FlatFileItemReader;
import org.springframework.batch.item.file.builder.FlatFileItemReaderBuilder;
import org.springframework.batch.item.file.mapping.RecordFieldSetMapper;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.io.FileSystemResource;
import org.springframework.transaction.PlatformTransactionManager;

import java.math.BigDecimal;
import java.math.RoundingMode;

@Configuration
public class ComplexBusinessLogicConfig {

    private final JobRepository jobRepository;
    private final PlatformTransactionManager transactionManager;

    public ComplexBusinessLogicConfig(JobRepository jobRepository,
                                      PlatformTransactionManager transactionManager) {
        this.jobRepository = jobRepository;
        this.transactionManager = transactionManager;
    }

    @Bean
    public Job complexReconciliationJob() {
        // This job contains complex business logic that would be painful to express
        // in a visual ETL tool: multi-currency conversion, fuzzy matching,
        // and jurisdiction-specific compliance rules. All in plain Java, testable
        // with standard JUnit and debuggable in any IDE.
        return new JobBuilder("complexReconciliationJob", jobRepository)
                .start(complexReconciliationStep())
                .build();
    }

    @Bean
    public Step complexReconciliationStep() {
        return new StepBuilder("complexReconciliationStep", jobRepository)
                .<TransactionRecord, ReconciledTransaction>chunk(100, transactionManager)
                .reader(csvReader())
                .processor(complexProcessor())
                .writer(resultWriter())
                .build();
    }

    @Bean
    public FlatFileItemReader<TransactionRecord> csvReader() {
        return new FlatFileItemReaderBuilder<TransactionRecord>()
                .name("csvReader")
                .resource(new FileSystemResource("data/transactions.csv"))
                .linesToSkip(1)
                .delimited()
                .names("transactionId", "accountId", "amount", "currency", "transactionDate", "status")
                .fieldSetMapper(new RecordFieldSetMapper<>(TransactionRecord.class))
                .build();
    }

    @Bean
    public ItemProcessor<TransactionRecord, ReconciledTransaction> complexProcessor() {
        return record -> {
            // Complex business logic that is trivial to test in JUnit but
            // would require embedded scripts in a visual ETL tool.
            BigDecimal usdAmount = convertToUsd(record.amount(), record.currency());

            boolean matched = usdAmount.compareTo(BigDecimal.ZERO) > 0
                    && "SETTLED".equals(record.status())
                    && isWithinComplianceWindow(record);

            return new ReconciledTransaction(
                    record.transactionId(),
                    record.accountId(),
                    usdAmount,
                    matched ? "MATCHED" : "MISMATCHED",
                    matched ? "Multi-currency settlement passed" : "Compliance or amount failure"
            );
        };
    }

    // Business logic that is trivial to unit test in isolation
    private BigDecimal convertToUsd(BigDecimal amount, String currency) {
        // Simplified: in production, this queries a historical exchange rate table
        return switch (currency) {
            case "USD" -> amount;
            case "EUR" -> amount.multiply(new BigDecimal("1.08")).setScale(2, RoundingMode.HALF_UP);
            case "GBP" -> amount.multiply(new BigDecimal("1.27")).setScale(2, RoundingMode.HALF_UP);
            default -> amount; // fallback
        };
    }

    private boolean isWithinComplianceWindow(TransactionRecord record) {
        // Simplified: in production, this checks jurisdiction-specific rules
        return record.transactionDate() != null
                && !record.transactionDate().isAfter(java.time.LocalDate.now());
    }

    @Bean
    public ItemWriter<ReconciledTransaction> resultWriter() {
        return chunk -> chunk.forEach(tx ->
            System.out.printf("[Complex] %s: %s (USD %s)%n",
                    tx.transactionId(), tx.reconciliationStatus(), tx.amount())
        );
    }
}

package com.example.reconciliation.batch;

import com.example.reconciliation.domain.ReconciledTransaction;
import com.example.reconciliation.domain.TransactionRecord;
import org.springframework.batch.core.Job;
import org.springframework.batch.core.Step;
import org.springframework.batch.core.job.builder.JobBuilder;
import org.springframework.batch.core.repository.JobRepository;
import org.springframework.batch.core.step.builder.StepBuilder;
import org.springframework.batch.item.ItemProcessor;
import org.springframework.batch.item.ItemReader;
import org.springframework.batch.item.ItemWriter;
import org.springframework.batch.item.file.FlatFileItemReader;
import org.springframework.batch.item.file.builder.FlatFileItemReaderBuilder;
import org.springframework.batch.item.file.mapping.RecordFieldSetMapper;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.io.FileSystemResource;
import org.springframework.transaction.PlatformTransactionManager;

import java.math.BigDecimal;

@Configuration
public class FivePillarsDemoConfig {

    private final JobRepository jobRepository;
    private final PlatformTransactionManager transactionManager;

    public FivePillarsDemoConfig(JobRepository jobRepository,
                                 PlatformTransactionManager transactionManager) {
        this.jobRepository = jobRepository;
        this.transactionManager = transactionManager;
    }

    @Bean
    public Job fivePillarsJob() {
        // This single job demonstrates all five pillars:
        // 1. CHUNK PROCESSING: chunk(100) bounds memory and transaction scope.
        // 2. RESTARTABILITY: FlatFileItemReader stores line number in ExecutionContext.
        // 3. SKIP/RETRY: faultTolerant() with skipLimit and retryLimit (see Section 9).
        // 4. SCALABILITY: currently single-threaded (Section 11 shows how to scale).
        // 5. TRANSACTION MANAGEMENT: PlatformTransactionManager commits each chunk atomically.
        return new JobBuilder("fivePillarsJob", jobRepository)
                .start(demonstrationStep())
                .build();
    }

    @Bean
    public Step demonstrationStep() {
        return new StepBuilder("demonstrationStep", jobRepository)
                .<TransactionRecord, ReconciledTransaction>chunk(100, transactionManager)
                .reader(csvReader())
                .processor(processor())
                .writer(writer())
                // Pillar 3: Skip/Retry — skip bad records up to a limit, retry transient errors
                .faultTolerant()
                .skipLimit(10)
                .skip(IllegalArgumentException.class)
                .retryLimit(3)
                .retry(org.springframework.dao.TransientDataAccessException.class)
                .build();
    }

    @Bean
    public FlatFileItemReader<TransactionRecord> csvReader() {
        // Pillar 2: Restartability — FlatFileItemReader automatically stores
        // the current line number in the StepExecution ExecutionContext
        // after each chunk commit, enabling resume-from-line-N on restart.
        return new FlatFileItemReaderBuilder<TransactionRecord>()
                .name("csvReader")
                .resource(new FileSystemResource("data/transactions.csv"))
                .linesToSkip(1)
                .delimited()
                .names("transactionId", "accountId", "amount", "currency", "transactionDate", "status")
                .fieldSetMapper(new RecordFieldSetMapper<>(TransactionRecord.class))
                .build();
    }

    @Bean
    public ItemProcessor<TransactionRecord, ReconciledTransaction> processor() {
        return record -> {
            if (record.amount() == null || record.amount().compareTo(BigDecimal.ZERO) <= 0) {
                // This will trigger a skip (pillar 3) after the skipLimit is configured
                throw new IllegalArgumentException("Invalid amount for " + record.transactionId());
            }
            boolean matched = "SETTLED".equals(record.status());
            return new ReconciledTransaction(
                    record.transactionId(),
                    record.accountId(),
                    record.amount(),
                    matched ? "MATCHED" : "MISMATCHED",
                    "Five pillars demo"
            );
        };
    }

    @Bean
    public ItemWriter<ReconciledTransaction> writer() {
        // Pillar 5: Transaction Management — this writer is called inside
        // the chunk transaction. If any item in the chunk fails, the entire
        // chunk of 100 items rolls back. No partial writes.
        return chunk -> chunk.forEach(tx ->
            System.out.printf("[Pillars] %s -> %s%n", tx.transactionId(), tx.reconciliationStatus())
        );
    }
}
